/* Give each entry a distinct outpoint/script so we can tell them apart
 * after serials get rewritten. */
static void add_input_with_serial(struct wally_psbt *psbt,
				  u64 serial_id,
				  u8 tag)
{
	struct bitcoin_outpoint outpoint;
	struct wally_psbt_input *in;

	memset(&outpoint, tag, sizeof(outpoint));
	in = psbt_append_input(psbt, &outpoint, tag, NULL, NULL, NULL);
	if (!in)
		abort();
	psbt_input_set_serial_id(psbt, in, serial_id);
}

static void add_output_with_serial(struct wally_psbt *psbt,
				   u64 serial_id,
				   u8 tag)
{
	u8 *script;
	struct wally_psbt_output *out;

	script = tal_arr(tmpctx, u8, 20);
	memset(script, tag, 20);
	out = psbt_append_output(psbt, script, amount_sat(tag * 1000));
	if (!out)
		abort();
	psbt_output_set_serial_id(psbt, out, serial_id);
}

/* The input at `idx` must carry `serial` and the outpoint tag `tag` */
static void check_input(const struct wally_psbt *psbt, size_t idx,
			u64 serial, u8 tag)
{
	struct bitcoin_outpoint outpoint;
	u64 found_serial;

	assert(idx < psbt->num_inputs);
	assert(psbt_get_serial_id(&psbt->inputs[idx].unknowns, &found_serial));
	assert(found_serial == serial);

	wally_psbt_input_get_outpoint(&psbt->inputs[idx], &outpoint);
	for (size_t i = 0; i < sizeof(outpoint.txid); i++)
		assert(((u8 *)&outpoint.txid)[i] == tag);
}

static u64 *serial_list(u64 serial)
{
	u64 *list = tal_arr(tmpctx, u64, 1);
	list[0] = serial;
	return list;
}

/* Peer (odd) additions land on the parent even-pair normalized;
 * our unlisted even additions are ignored */
static void test_normalize_and_ignore(void)
{
	struct wally_psbt *parent, *node_old, *node_new;
	bool changed;

	parent = create_psbt(tmpctx, 1, 1, 0);
	add_input_with_serial(parent, 2, 0x02);
	add_output_with_serial(parent, 4, 0x04);

	node_old = clone_psbt(tmpctx, parent);
	node_new = clone_psbt(tmpctx, node_old);
	/* Peer adds odd input 11 + odd output 21; we also see an even
	 * entry (102) that's ours-but-unlisted (e.g. already accounted) */
	add_input_with_serial(node_new, 11, 0x0b);
	add_output_with_serial(node_new, 21, 0x15);
	add_input_with_serial(node_new, 102, 0x66);

	changed = false;
	assert(psbt_multiview_merge(tmpctx, node_old, node_new,
				    NULL, NULL, &changed, &parent));
	assert(changed);

	/* Odd entries normalized down a serial */
	assert(psbt_find_serial_input(parent, 10) != -1);
	assert(psbt_find_serial_input(parent, 11) == -1);
	assert(psbt_find_serial_output(parent, 20) != -1);
	assert(psbt_find_serial_output(parent, 21) == -1);
	/* Unlisted even entry did not land on the parent */
	assert(psbt_find_serial_input(parent, 102) == -1);
	/* Original entries intact */
	assert(psbt_find_serial_input(parent, 2) != -1);
	assert(psbt_find_serial_output(parent, 4) != -1);
	assert(parent->num_inputs == 2);
	assert(parent->num_outputs == 2);
}

/* A serial collision on the parent rejects the merge, parent untouched */
static void test_collision(void)
{
	struct wally_psbt *parent, *node_old, *node_new;
	bool changed;

	parent = create_psbt(tmpctx, 1, 1, 0);
	add_input_with_serial(parent, 10, 0x0a);

	node_old = clone_psbt(tmpctx, parent);
	node_new = clone_psbt(tmpctx, node_old);
	/* Peer's odd 11 normalizes to 10 -- taken */
	add_input_with_serial(node_new, 11, 0x0b);

	changed = true;
	assert(!psbt_multiview_merge(tmpctx, node_old, node_new,
				     NULL, NULL, &changed, &parent));
	assert(parent->num_inputs == 1);
	check_input(parent, 0, 10, 0x0a);
}

/* Preserve-listed even (daemon-minted) entries are copied verbatim */
static void test_preserve_lists(void)
{
	struct wally_psbt *parent, *node_old, *node_new;
	bool changed;

	parent = create_psbt(tmpctx, 1, 1, 0);
	add_input_with_serial(parent, 2, 0x02);

	node_old = clone_psbt(tmpctx, parent);
	node_new = clone_psbt(tmpctx, node_old);
	/* Daemon minted an even funding input + funding output */
	add_input_with_serial(node_new, 100, 0x64);
	add_output_with_serial(node_new, 200, 0xc8);

	changed = false;
	assert(psbt_multiview_merge(tmpctx, node_old, node_new,
				    serial_list(100), serial_list(200),
				    &changed, &parent));
	assert(changed);
	assert(psbt_find_serial_input(parent, 100) != -1);
	assert(psbt_find_serial_output(parent, 200) != -1);

	/* Colliding preserve entry rejects */
	node_old = clone_psbt(tmpctx, parent);
	node_new = clone_psbt(tmpctx, node_old);
	add_input_with_serial(node_new, 100, 0x65);
	/* Trick the changeset into seeing it as an addition: the old view
	 * lacks this outpoint, and serial 100 already sits on the parent */
	psbt_rm_input(node_old, psbt_find_serial_input(node_old, 100));

	assert(!psbt_multiview_merge(tmpctx, node_old, node_new,
				     serial_list(100), NULL, NULL, &parent));
}

/* Peer removals apply at the even-pair; removing our entry fails */
static void test_removals(void)
{
	struct wally_psbt *parent, *node_old, *node_new;
	bool changed;
	int idx;

	parent = create_psbt(tmpctx, 1, 1, 0);
	add_input_with_serial(parent, 2, 0x02);

	/* Merge a peer input (11 -> 10) */
	node_old = clone_psbt(tmpctx, parent);
	node_new = clone_psbt(tmpctx, node_old);
	add_input_with_serial(node_new, 11, 0x0b);
	assert(psbt_multiview_merge(tmpctx, node_old, node_new,
				    NULL, NULL, NULL, &parent));
	assert(psbt_find_serial_input(parent, 10) != -1);

	/* Peer removes it: node view had 11, new view doesn't */
	node_old = clone_psbt(tmpctx, node_new);
	node_new = clone_psbt(tmpctx, node_old);
	idx = psbt_find_serial_input(node_new, 11);
	assert(idx != -1);
	psbt_rm_input(node_new, idx);

	changed = false;
	assert(psbt_multiview_merge(tmpctx, node_old, node_new,
				    NULL, NULL, &changed, &parent));
	assert(changed);
	assert(psbt_find_serial_input(parent, 10) == -1);

	/* "Peer" removing our even entry is rejected */
	node_old = clone_psbt(tmpctx, node_new);
	node_new = clone_psbt(tmpctx, node_old);
	idx = psbt_find_serial_input(node_new, 2);
	assert(idx != -1);
	psbt_rm_input(node_new, idx);

	assert(!psbt_multiview_merge(tmpctx, node_old, node_new,
				     NULL, NULL, NULL, &parent));
	assert(psbt_find_serial_input(parent, 2) != -1);
}

/* No effective change -> parent_changed false */
static void test_unchanged(void)
{
	struct wally_psbt *parent, *node_old, *node_new;
	bool changed;

	parent = create_psbt(tmpctx, 1, 1, 0);
	add_input_with_serial(parent, 2, 0x02);

	node_old = clone_psbt(tmpctx, parent);
	node_new = clone_psbt(tmpctx, node_old);

	changed = true;
	assert(psbt_multiview_merge(tmpctx, node_old, node_new,
				    NULL, NULL, &changed, &parent));
	assert(!changed);
}

/* Two peers, one parent: rebuilds restore only each peer's own odd
 * serials and every psbt sorts to the same entry order */
static void test_three_negotiations(void)
{
	struct wally_psbt *parent, *node_a, *node_b, *tmp_old, *tmp_new;

	parent = create_psbt(tmpctx, 1, 1, 0);
	add_input_with_serial(parent, 2, 0x02);

	/* Peer A contributes odd input 11 */
	node_a = clone_psbt(tmpctx, parent);
	tmp_old = clone_psbt(tmpctx, node_a);
	tmp_new = clone_psbt(tmpctx, node_a);
	add_input_with_serial(tmp_new, 11, 0x0b);
	assert(psbt_multiview_merge(tmpctx, tmp_old, tmp_new,
				    NULL, NULL, NULL, &parent));
	node_a = tmp_new;

	/* Peer B contributes odd input 31 */
	node_b = clone_psbt(tmpctx, parent);
	tmp_old = clone_psbt(tmpctx, node_b);
	tmp_new = clone_psbt(tmpctx, node_b);
	add_input_with_serial(tmp_new, 31, 0x1f);
	assert(psbt_multiview_merge(tmpctx, tmp_old, tmp_new,
				    NULL, NULL, NULL, &parent));
	node_b = tmp_new;

	/* Rebuild both views from the parent */
	assert(psbt_multiview_rebuild_node(tmpctx, parent, &node_a));
	assert(psbt_multiview_rebuild_node(tmpctx, parent, &node_b));

	/* A sees its own 11, B's masked as 30 */
	assert(psbt_find_serial_input(node_a, 11) != -1);
	assert(psbt_find_serial_input(node_a, 30) != -1);
	assert(psbt_find_serial_input(node_a, 31) == -1);
	assert(psbt_find_serial_input(node_a, 10) == -1);

	/* B sees its own 31, A's masked as 10 */
	assert(psbt_find_serial_input(node_b, 31) != -1);
	assert(psbt_find_serial_input(node_b, 10) != -1);
	assert(psbt_find_serial_input(node_b, 11) == -1);
	assert(psbt_find_serial_input(node_b, 30) == -1);

	/* Sorted by serial, all three agree on entry order (and would
	 * therefore agree on the txid) */
	psbt_sort_by_serial_id(parent);
	psbt_sort_by_serial_id(node_a);
	psbt_sort_by_serial_id(node_b);

	assert(parent->num_inputs == 3);
	assert(node_a->num_inputs == 3);
	assert(node_b->num_inputs == 3);

	/* order: ours(2) < A's(10/11) < B's(30/31) */
	check_input(parent, 0, 2, 0x02);
	check_input(parent, 1, 10, 0x0b);
	check_input(parent, 2, 30, 0x1f);
	check_input(node_a, 0, 2, 0x02);
	check_input(node_a, 1, 11, 0x0b);
	check_input(node_a, 2, 30, 0x1f);
	check_input(node_b, 0, 2, 0x02);
	check_input(node_b, 1, 10, 0x0b);
	check_input(node_b, 2, 31, 0x1f);
}

int main(int argc, const char *argv[])
{
	common_setup(argv[0]);
	chainparams = chainparams_for_network("bitcoin");

	test_normalize_and_ignore();
	test_collision();
	test_preserve_lists();
	test_removals();
	test_unchanged();
	test_three_negotiations();

	common_shutdown();
	return 0;
}
